insert into exercise (id, title, statement, difficulty, language, function_name, max_repeated_failures, max_idle_minutes, created_by, created_at, updated_at) values
  ('40000000-0000-4000-8000-000000000001', 'Contar números pares', 'Escribe una función `contarPares` que reciba un número entero `n` y devuelva cuántos números pares hay entre 1 y `n`, ambos incluidos. Si `n` es menor que 2, la función debe devolver 0.', 'initial', 'javascript', 'contarPares', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000002', 'Tabla de multiplicar', 'Escribe una función `tablaMultiplicar` que reciba un número entero `n` y devuelva su tabla de multiplicar del 1 al 10 como un único texto. Cada línea sigue el formato `n x i = resultado` y las líneas se separan con un salto de línea (`\n`), sin salto al final. Si `n` es 0, todas las líneas dan 0.', 'initial', 'javascript', 'tablaMultiplicar', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000003', 'Suma de los elementos de un vector', 'Escribe una función `suma` que reciba un vector de números enteros y devuelva la suma de todos sus elementos. Si el vector está vacío, la función debe devolver 0.', 'medium', 'javascript', 'suma', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000004', 'Máximo de un vector', 'Escribe una función `maximo` que reciba un vector de números y devuelva el mayor de sus elementos. Ten en cuenta que todos pueden ser negativos. Si el vector está vacío, la función debe devolver `null`.', 'medium', 'javascript', 'maximo', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000005', 'Invertir un vector', 'Escribe una función `invertir` que reciba un vector y devuelva un vector nuevo con los mismos elementos en orden inverso. Resuélvelo recorriendo el vector con índices, sin usar `reverse()`. Si el vector está vacío, devuelve un vector vacío.', 'advanced', 'javascript', 'invertir', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000006', 'Contar vocales en una cadena', 'Escribe una función `contarVocales` que reciba un texto y devuelva cuántas vocales contiene, sin distinguir mayúsculas de minúsculas. Las vocales con tilde (á, é, í, ó, ú) también cuentan. Si el texto está vacío, la función debe devolver 0.', 'extension', 'javascript', 'contarVocales', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000007', 'Media de un vector con dos decimales', 'Escribe una función `media` que reciba un vector de números y devuelva su media como texto con exactamente dos decimales, por ejemplo `"2.50"`. Si el vector está vacío, la función debe devolver `"0.00"`.', 'extension', 'javascript', 'media', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z'),
  ('40000000-0000-4000-8000-000000000008', 'Buscar un valor con parada temprana', 'Escribe una función `buscar` que reciba un vector y un valor, y devuelva la posición de la primera vez que aparece ese valor, dejando de recorrer el vector en cuanto lo encuentre. Si el valor no aparece, la función debe devolver -1.', 'extension', 'javascript', 'buscar', 3, 4, '10000000-0000-4000-8000-000000000002', '2026-09-28T16:00:00.000Z', '2026-09-28T16:00:00.000Z');

